sys_script_include.script:
var CodeAutoFixerAjax = Class.create();
CodeAutoFixerAjax.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    applyFix: function() {
        var logId = this.getParameter('sysparm_log_id');
        var engine = new CodeAutoFixerEngine();
        return engine.applyFix(logId) ? 'success' : 'error';
    },

    rejectFix: function() {
        var logId = this.getParameter('sysparm_log_id');
        var engine = new CodeAutoFixerEngine();
        return engine.rejectFix(logId) ? 'success' : 'error';
    },

    type: 'CodeAutoFixerAjax'
});
